type ClaimFields = { amount?: string; date?: string; note?: string; corrects?: string; ref?: string; tags?: string };

/** Fill the claim form. `clear` (an add) also empties every field the test does not give (a
 *  blank date takes the default), so nothing typed for a refused add carries into this one; an
 *  edit leaves the fields it is not given as the editor filled them. */
async function fillClaimForm(r: Locator, f: ClaimFields, clear = false) {
  for (const key of ['amount', 'date', 'note', 'corrects', 'ref', 'tags'] as const) {
    const v = f[key];
    if (v !== undefined) await r.getByTestId(`claim-form-${key}`).fill(v);
    else if (clear) await setField(r, `claim-form-${key}`, undefined);
  }
}

/** Add a claim from the person's row. The new claim's id, or null when refused. */
export async function addClaim(page: Page, personId: string, f: ClaimFields & { amount: string }): Promise<string | null> {
  const r = row(page, personId);
  const before = await ids(claimRows(r), 'claim-row-');
  await fillClaimForm(r, f, true);
  await r.getByTestId('claim-form-submit').click();
  let added: string | null = null;
  const ok = await until(page, async () => (added = await addedClaim(r, before, f)) !== null,
    r.getByTestId('claim-form-error'), 'add claim');
  return ok ? added : null;
}

// Playwright config. Tests bind to data-testid only and assert through the UI. The app is already
// running (started by bin/e2e), so no webServer here.
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './specs',
  use: {
    baseURL: process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`,
    // The contract attribute is data-testid — Playwright's default, so no testIdAttribute override
    // needed. Strict awaiting on data-testid presence is the flake guard.
  },
  // Every spec arranges its own data through the screens on a sheet id of its own and reads the
  // audit file filtered by that id, so specs never share data. workers:1 keeps the suite serial
  // against the one shared app, so a failure stays attributable to one spec.
  fullyParallel: false,
  workers: 1,
  reporter: [['list']],
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // Headless Chromium needs its own sandbox off and
        // shared memory in /tmp, or renderer/GPU child processes crash. Harmless elsewhere too.
        launchOptions: { args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] },
      },
    },
  ],
});
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )

